import{_ as t,o as e,c as s,a3 as o}from"./chunks/framework.DdpBa4_E.js";const _="/ReadBooks/assets/image-027.CxgtS1-4.jpg",p="/ReadBooks/assets/image-028.DWr06erh.jpg",r="/ReadBooks/assets/image-029.4_wMREH9.jpg",i="/ReadBooks/assets/image-030.CMrm730X.jpg",f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/74-每天一条甜蜜短信就那么难吗？.md","filePath":"books/attached/74-每天一条甜蜜短信就那么难吗？.md","lastUpdated":1794316978000}'),n={name:"books/attached/74-每天一条甜蜜短信就那么难吗？.md"};function d(c,a,l,m,g,h){return e(),s("div",null,[...a[0]||(a[0]=[o('<h3 id="每天一条甜蜜短信就那么难吗" tabindex="-1">每天一条甜蜜短信就那么难吗？ <a class="header-anchor" href="#每天一条甜蜜短信就那么难吗" aria-label="Permalink to &quot;每天一条甜蜜短信就那么难吗？&quot;">​</a></h3><p>我们为本书收集素材而访问乔治娅（Georgia）和亨利（Henry）时，他们还处于整天争吵的状态。亨利觉得自己做什么都不能令乔治娅满意，自己总是被对方指手画脚、吹毛求疵。而乔治娅感觉亨利没有尽到婚姻中应尽的责任。她每天都要催着丈夫去做一些鸡毛蒜皮的事情，家里什么决定都要自己来做，从给亨利的妈妈买生日礼物到租房子的事。她在这段关系中，感觉到孤立无援。</p><p>通过观察行为模式，乔治娅显然属于焦虑型依恋风格，她常常会因为一件事情而陷入长期的烦恼。亨利在工作日没有时间跟她沟通，她就会不停打电话发短信，可是亨利也很少会回复。乔治娅的亲密关系目录如下：</p><p><img src="'+_+'" alt="" loading="lazy"></p><p><img src="'+p+'" alt="" loading="lazy"></p><p>属于回避型依恋风格的亨利，每天要忙于应付病人，因此对乔治娅的电话和短信轰炸感觉非常恼火。而每次给她回拨过去，对方一开口就是满腔责怪，整个谈话最后便不欢而散。而纵观他的亲密关系目录，是下面这样的：</p><p><img src="'+r+'" alt="" loading="lazy"></p><p><img src="'+i+'" alt="" loading="lazy"></p><p>当乔治娅和亨利将自己的亲密关系行为模式梳理出来，我们会发现他们看待同一情景的方式是不一样的。从亨利的角度，他忽视妻子的需求，轻视妻子的依赖，长此以往就导致事情变得越来越糟，关系中的幸福感也日渐流失。而在乔治娅的视角中，她使用的一系列防御机制只会将亨利越推越远，永远达不到她想要获得陪伴的预期目的。每当坐下来谈论这件事情时，两人都准备了一肚子的道理。亨利说自己白天并不是不会想她，只是工作太忙，没时间放下手头的事情打电话给他。而对乔治娅来说，她必须不断确定亨利在两人分离期间，也是不断想着她的。她可以理解丈夫工作忙，但自己还是很需要整天都和丈夫保持联系，才能感觉到亲密。</p><p>后来他们找到了一个很棒的解决办法：亨利要事先编辑好一条短信息，每当自己想念乔治娅的时候就发给她。这样一来既不会浪费他的时间，又能很好地安抚乔治娅的焦虑。这个方法对他们俩的关系来说堪称奇效。对乔治娅来说，一天“想念”短信让她很快从焦虑中平复下来，专心投入工作。而亨利也不会觉得乔治娅的不断叨扰影响了自己的事业，从而不胜其烦。事实上，借鉴了自己上司和妻子的特别处理方式之后，他深深体会到亲密关系中的安全基地，对双方的事业会产生多大的好处。而两人晚上回家见面时，所有的紧张都会一扫而空，一切的欲求不满和敌意也都不复存在。</p>',10)])])}const u=t(n,[["render",d]]);export{f as __pageData,u as default};
